%% checkCanCodec.m
% Checks the MATLAB CAN codec (canPut / canGet / bmsCanDb, 10. CAN/matlab) against test
% vectors encoded by cantools from bmsCan.dbc (canVectors.json, tools/genMatlab.py):
% every vector must encode to the same 8 bytes, and decode back to the same values.
% The Pi side uses C code generated by cantools from the same DBC (10. CAN/pi/bms_can.c).

S = bmsCanDb();
V = jsondecode(fileread(which("canVectors.json")));
nBad = 0;  maxErr = 0;
for k = 1:numel(V)
    v = V(k);  names = fieldnames(v.values);  d = zeros(8, 1, "uint8");
    for j = 1:numel(names), d = canPut(d, S.(v.msg).(names{j}), v.values.(names{j})); end
    ok = isequal(double(d), v.bytes(:));
    for j = 1:numel(names)
        spec = S.(v.msg).(names{j});
        e = abs(canGet(d, spec) - v.values.(names{j}));  maxErr = max(maxErr, e / spec(5));
        ok = ok && e <= spec(5) / 2 + 1e-9;
    end
    if ~ok, nBad = nBad + 1; fprintf("   FAIL %s: %s vs %s\n", v.msg, mat2str(double(d')), mat2str(v.bytes')); end
end
fprintf("%d vectors, %d mismatches, max decode error %.3g LSB\nOverall: %s\n", numel(V), nBad, maxErr, ...
    string(ifelse(nBad == 0, "PASS", "FAIL")));
function o = ifelse(c, a, b), if c, o = a; else, o = b; end, end
